Card("p43","vehicle_road","وعكة صحية أثناء السفر","997","استجابة — جهّز المعلومات واتصل بالرقم المناسب","t","جهّز اسم المصاب وأعراضه وأدويته وحساسياته وموقعك الدقيق قبل أن تتصل.",listOf("انتقل إلى مكان آمن واطلب مساعدة موظفي الموقع.","في المملكة: 997 للإسعاف، 993 لحوادث المرور، و911 للطوارئ الموحدة.","جهّز اسم المصاب وأعراضه وأدويته وحساسياته وموقعك الدقيق.","للسفر خارج المملكة، استخدم رقم الطوارئ المحلي ووثائق التأمين."),listOf("لا تؤجل الاتصال بالإسعاف عند أعراض شديدة."),listOf("راجع الطبيب قبل السفر بـ4 إلى 6 أسابيع عند الحمل أو الأمراض المزمنة، وتحقق من اللقاحات المطلوبة."),listOf("السفر","المركبة والطريق"),listOf(Link("وزارة الصحة: صحة المسافر","https://www.moh.gov.sa/awarenessplateform/seasonalandfestivalhealth/pages/healthytravel.aspx")),listOf()),
Card("p44","weather_outdoor","الزحام والتدافع (حج وعمرة ومناسبات)","911","تحذير — الوقاية والتصرف في الزحام الشديد","w","ابقَ واقفاً مهما حدث؛ السقوط في الزحام هو الخطر الأكبر. وابتعد مبكراً قبل أن يشتد الضغط.",listOf("اتجه مبكراً إلى حافة الحشد أو مخرج جانبي عند أول إحساس بتزايد الضغط، ولا تنتظر حتى تصبح الحركة صعبة.","ارفع ذراعيك أمام صدرك مثل الملاكم وقرّب المرفقين لتحمي صدرك وتحتفظ بمساحة تتنفس فيها.","سر مع اتجاه الحشد لا ضده، وانحرف تدريجياً بزاوية نحو الجانب، ولا تقاوم الموجة.","لا تنحنِ لالتقاط شيء سقط منك. إذا سقطت، انهض بسرعة، وحمِ رأسك ورقبتك بذراعيك أثناء النهوض.","اتبع إرشادات رجال الأمن والمنظمين، وأبلغ أقرب نقطة أمنية أو اتصل بـ911 إذا رأيت شخصاً سقط أو تعثر."),listOf("لا تدخل ممراً ضيقاً مزدحماً ولا تقف عند الحواجز والجدران؛ فهي مواضع الضغط الأشد.","لا تفلت يد طفل أو كبير سن؛ استخدم سواراً تعريفياً ونقطة التقاء متفقاً عليها.","لا تدفع الآخرين محاولاً التقدم."),listOf("الاتفاق مع الأسرة على نقطة تجمع ورقم اتصال قبل الدخول.","سوار تعريفي للأطفال وكبار السن وجوال مشحون.","حذاء مريح مغلق."),listOf("السفر","التخييم","الاستراحة","المدرسة"),listOf(),listOf()),
Card("p45","first_aid","الصيام وهبوط السكر أو الجفاف (رمضان)","937","رمضان — الحفاظ على النفس مقدّم على إتمام الصوم","w","إذا ظهرت علامات هبوط السكر أو الجفاف الشديد أثناء الصيام فسلامة النفس مقدّمة: يجوز الفطر ثم الإسعاف. واسأل أهل العلم عن القضاء.",listOf("اجلس في مكان بارد وأوقف المجهود، وانتبه للأعراض: رجفة، تعرق بارد، خفقان، دوخة، صداع شديد، جفاف الفم، تشوش.","لمريض السكري: قس السكر إن توفر الجهاز. وإن كان أقل من 70 ملجم/ديسيلتر أو ظهرت الأعراض فأفطر فوراً بما يرفع السكر سريعاً (عصير أو سكر مذاب في ماء).","لمن يعاني دوخة أو جفافاً دون السكري: أفطر وارشف الماء أو محلول الإماهة على دفعات صغيرة، وبرّد الجسم في مكان مظلل.","اتصل بـ937 للاستشارة، وبـ997 فوراً عند الإغماء أو التشنج أو التشوش أو العجز عن البلع. لا تعطِ فاقد الوعي شيئاً بالفم.","بعد التحسن تناول وجبة خفيفة فيها نشويات وبروتين، وراجع الطبيب قبل العودة للصيام، خاصة مرضى السكري والقلب والكلى."),listOf("لا تواصل الصيام رغم أعراض هبوط السكر أو الإغماء؛ التأخر خطر على الدماغ.","لا تعطِ طعاماً أو شراباً لفاقد الوعي.","لا تغيّر جرعات أدوية السكري أو الضغط أو توقفها من نفسك دون الطبيب."),listOf("قبل رمضان: استشر طبيبك لضبط جرعات الأدوية ومواعيدها.","جهاز قياس السكر وعصير أو تمر في متناول اليد.","تجنب الجهد والشمس وقت الذروة."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: انخفاض السكر","https://www.moh.gov.sa/healthawareness/educationalcontent/diseases/diabetic/pages/hypoglycemia-low-blood-glucose-levels.aspx"),Link("وزارة الصحة: خدمة 937","https://www.moh.gov.sa/937/pages/default.aspx")),listOf()),
Card("p46","weather_outdoor","السيول والأمطار الغزيرة: قبل وأثناء وبعد","998","تحذير الدفاع المدني — ابتعد عن مجاري السيول","t","لا تعبر الأودية ولا تقف قرب مجاري السيول؛ السيل قد يصل سريعاً حتى لو لم يمطر عندك.",listOf("قبل الموسم: تابع تنبيهات الدفاع المدني والأرصاد، وجهّز حقيبة فيها ماء ومصباح وشاحن متنقل مشحون وأدويتك وأوراقك المهمة.","أثناء المطر الغزير: ابقَ في مكان مرتفع وآمن، وابتعد عن الأودية والمنخفضات والأنفاق وأعمدة الكهرباء.","إذا ارتفع الماء في المنزل: ارفع الأجهزة والوثائق للأعلى، وافصل الكهرباء من القاطع إن كان الوصول إليه جافاً وآمناً، وانتقل إلى طابق أعلى.","عند الخطر المباشر أو الاحتجاز اتصل بـ998 (أو 911) وأبلغ موقعك بدقة، ولا تمشِ في مياه جارية.","بعد السيل: لا تقترب من أسلاك ساقطة، وتجنب مياه السيل الملوثة، ولا تستخدم أجهزة مبللة، وتأكد من سلامة المبنى قبل الدخول."),listOf("لا تعبر مجرى ماء بمركبة أو سيراً مهما بدا ضحلاً.","لا تلمس أجهزة كهربائية وأنت مبلل أو واقف في الماء.","لا تتنزه عند الأودية أثناء الأمطار."),listOf("حقيبة طوارئ جاهزة ومصباح وشاحن متنقل.","حفظ أرقام 998 و997 و911."),listOf("الاستراحة","التخييم","السفر"),listOf(Link("الدفاع المدني السعودي: السلامة والإنذار","https://998.gov.sa/")),listOf()),
Card("p47","weather_outdoor","الحج والعمرة: الوقاية من الحرارة والإعياء","997","وقاية وإسعاف — الحرارة والمشي الطويل","p","الوقاية قبل العلاج: اشرب قبل أن تعطش، واستظل واستَرِح، وتوقف عند أول علامة إعياء.",listOf("اشرب الماء بانتظام على رشفات طوال اليوم حتى دون عطش، وخذ استراحات في الظل.","استعمل المظلة وغطِّ الرأس وارتدِ ملابس خفيفة فاتحة، واختر أوقاتاً أقل حرارة للطواف والسعي إن أمكن.","عند دوخة أو غثيان أو صداع أو تعرق شديد: توقف فوراً، واجلس في الظل أو مكان مكيف، وبرّد الجسم بالماء والمروحة.","إذا توقف التعرق أو احمرّ الجلد وسخن أو حدث تشوش أو إغماء: فهذه ضربة شمس، اتصل بـ997 فوراً وواصل التبريد حتى وصول الإسعاف.","اتفق مع مرافقيك على نقطة التقاء، وحمل بطاقة تعريف، وانتبه لكبار السن والأطفال أكثر."),listOf("لا تتجاهل الإعياء لإكمال النسك؛ الصحة أولوية.","لا تعتمد على المشروبات الغازية أو المنبهة بدل الماء.","لا تعطِ سوائل لمن فقد وعيه."),listOf("زجاجة ماء قابلة لإعادة التعبئة ومظلة.","محلول إماهة وحقيبة إسعافات صغيرة.","أرقام 997 و937 محفوظة."),listOf("السفر","التخييم"),listOf(Link("وزارة الصحة: ضربة الشمس","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/022.aspx"),Link("مراكز مكافحة الأمراض (CDC): الأمراض المرتبطة بالحرارة","https://www.cdc.gov/heat-health/")),listOf())
)
